import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";

export type StoreFunctionConfiguration = {
  /** The type of knowledge object, generated by the function (i.e., 'lookup') */
  type?: string;
  /** Configures where and how the data should be stored */
  destination?: string;
  /** The knowledge object's description */
  description?: string;
  /** Mapping event property names to output field names */
  fieldMapping?: Record<string, unknown>;
  /** Character to be used as value delimiter in output */
  separator?: string;
  /**
   * For existing files, an error is thrown if overwrite is false or the file is replaced if
   * overwrite is true
   */
  overwrite?: boolean;
  /** True will compress output, false leaves it as it is and auto decides based on size */
  compress?: string;
  /** Tee results to the next operator */
  tee?: boolean;
  /** Limits how many events can be stored */
  maxEvents?: number;
  /** Suppresses the timer-based export stats generating */
  suppressPreviews?: boolean;
};

export const storeFunctionConfigurationSchema: Schema<StoreFunctionConfiguration> =
  s.object<StoreFunctionConfiguration>({
    type: s.optional(s.string()),
    destination: s.optional(s.string()),
    description: s.optional(s.string()),
    fieldMapping: s.optional(s.record(s.string(), s.unknown())),
    separator: s.optional(s.string()),
    overwrite: s.optional(s.boolean()),
    compress: s.optional(s.string()),
    tee: s.optional(s.boolean()),
    maxEvents: s.optional(s.float64()),
    suppressPreviews: s.optional(s.boolean()),
  });
